import { Readable } from 'stream';
import { IGDBBackend } from './types/gdb';
import { NamedLogger } from './namedLogger';

interface Command {
    command: string;
    callback: (resultClass: string, resultData: any) => void;
}

type CommandQueue = {
    [key: string]: Command;
};

const DEFAULT_CHARSET = 'utf-8';
/**
 * Fixups for non-whatwg charset encodings in GDB known to effectively being
 * aliases for whatwg encodings.
 */
const FIXUPS_CHARSET = new Map<string, string>([['cp65001', 'utf-8']]);

export class MIParser {
    public static readonly CMD_QUEUE_CANCELLED =
        'MIParser command queue cancelled';
    /**
     * Encoding for GDB/MI cstring characters outside standard ASCII range.
     * Value has to match names known to TextDecoder API, see also
     * whatwg encodings (https://encoding.spec.whatwg.org/).
     * Defaults to 'utf-8' to match previous behavior.
     */
    protected _hostCharset = DEFAULT_CHARSET;
    protected logger: NamedLogger;
    protected line = '';
    protected pos = 0;

    protected commandQueue: CommandQueue = {};
    protected waitReady?: (value?: void | PromiseLike<void>) => void;

    constructor(
        protected gdb: IGDBBackend,
        protected name?: string
    ) {
        this.logger = new NamedLogger(name);
    }

    public set hostCharset(value: string | undefined) {
        // Empty string not included in map, returns undefined.
        const fixup = FIXUPS_CHARSET.get(value ?? '');
        this._hostCharset = fixup ?? value ?? DEFAULT_CHARSET;
        this.logger.verbose(
            `MIParser: Decoding GDB host character set as '${this._hostCharset}'`
        );
    }

    public get hostCharset(): string | undefined {
        return this._hostCharset;
    }

    public cancelQueue() {
        // Entries in the form of [key, callback]
        const entries = Object.entries(this.commandQueue);
        entries.forEach((entry) => {
            // Call callback with error to reject command promise
            entry[1].callback('error', {
                msg: MIParser.CMD_QUEUE_CANCELLED,
            });
            // Delete command by key
            delete this.commandQueue[entry[0]];
        });
    }

    public parse(stream: Readable): Promise<void> {
        return new Promise((resolve) => {
            this.waitReady = resolve;
            const lineBreakRegex = /\r?\n/;
            let buff = '';
            stream.on('data', (chunk) => {
                const newChunk = chunk.toString();
                let regexArray = lineBreakRegex.exec(newChunk);
                if (regexArray) {
                    regexArray.index += buff.length;
                }
                buff += newChunk;
                while (regexArray) {
                    const line = buff.slice(0, regexArray.index);
                    this.parseLine(line);
                    buff = buff.slice(regexArray.index + regexArray[0].length);
                    regexArray = lineBreakRegex.exec(buff);
                }
            });
        });
    }

    public parseLine(line: string) {
        this.line = line;
        this.pos = 0;
        this.handleLine();
    }

    public queueCommand(
        token: number,
        command: string,
        callback: (resultClass: string, resultData: any) => void
    ) {
        this.commandQueue[token] = { command, callback };
    }

    protected peek() {
        if (this.pos < this.line.length) {
            return this.line[this.pos];
        } else {
            return null;
        }
    }

    protected next() {
        if (this.pos < this.line.length) {
            return this.line[this.pos++];
        } else {
            return null;
        }
    }

    protected back() {
        this.pos--;
    }

    protected restOfLine() {
        return this.line.substr(this.pos);
    }

    protected handleToken(firstChar: string) {
        let token = firstChar;
        let c = this.next();
        while (c && c >= '0' && c <= '9') {
            token += c;
            c = this.next();
        }
        this.back();
        return token;
    }

    protected decodeCStringBytes(encodedBytes: number[]): string {
        const buffer = Buffer.from(encodedBytes);
        try {
            return new TextDecoder(this._hostCharset, { fatal: true }).decode(
                buffer
            );
        } catch (err) {
            this.logger.error(
                `Failed to decode code points (${this._hostCharset}) '${encodedBytes}'. ${JSON.stringify(err)}`
            );
        }
        // Return something even if garbage
        return String.fromCodePoint(...encodedBytes);
    }

    protected handleCString() {
        let c = this.next();
        if (!c || c !== '"') {
            return null;
        }

        let cstring = '';
        let octal = '';
        let encodedBytes = [];
        mainloop: for (c = this.next(); c; c = this.next()) {
            if (octal) {
                octal += c;
                if (octal.length == 3) {
                    // Octal sequence complete, save code point
                    encodedBytes.push(parseInt(octal, 8));
                    octal = '';
                }
                continue;
            }
            // End of octal sequence, convert accumulated code points
            if (c !== '\\' && encodedBytes.length) {
                cstring += this.decodeCStringBytes(encodedBytes);
                encodedBytes = [];
            }
            switch (c) {
                case '"':
                    break mainloop;
                case '\\':
                    c = this.next();
                    if (c) {
                        // End of octal sequence, convert and add accumulated code points
                        if (encodedBytes.length && (c < '0' || c > '7')) {
                            cstring += this.decodeCStringBytes(encodedBytes);
                            encodedBytes = [];
                        }
                        switch (c) {
                            case 'n':
                                cstring += '\n';
                                break;
                            case 't':
                                cstring += '\t';
                                break;
                            case 'r':
                                break;
                            case '0':
                            case '1':
                            case '2':
                            case '3':
                            case '4':
                            case '5':
                            case '6':
                            case '7':
                                octal = c;
                                break;
                            default:
                                cstring += c;
                        }
                    } else {
                        this.back();
                    }
                    break;
                default:
                    cstring += c;
            }
        }
        // Remaining code points, convert and add accumulated code points
        if (encodedBytes.length) {
            cstring += this.decodeCStringBytes(encodedBytes);
            encodedBytes = [];
        }
        return cstring;
    }

    protected handleString() {
        let str = '';
        for (let c = this.next(); c; c = this.next()) {
            if (c === '=' || c === ',') {
                this.back();
                return str;
            } else {
                str += c;
            }
        }
        return str;
    }

    protected handleObject() {
        let c = this.next();
        const result: any = {};
        if (c === '{') {
            c = this.next();
            if (c !== '"') {
                // oject contains name-value pairs
                while (c !== '}') {
                    if (c !== ',') {
                        this.back();
                    }
                    const name = this.handleString();
                    if (this.next() === '=') {
                        result[name] = this.handleValue();
                    }
                    c = this.next();
                }
            } else {
                // "object" contains just values
                this.back();
                let key = 0;
                while (c !== '}') {
                    const value = this.handleCString();
                    if (value) result[key++] = value;
                    c = this.next();
                }
            }
        }

        if (c === '}') {
            return result;
        } else {
            return null;
        }
    }

    protected handleArray() {
        let c = this.next();
        const result: any[] = [];
        if (c === '[') {
            c = this.next();
            while (c !== ']') {
                if (c !== ',') {
                    this.back();
                }
                result.push(this.handleValue());
                c = this.next();
            }
        }

        if (c === ']') {
            return result;
        } else {
            return null;
        }
    }

    protected handleValue(): any {
        const c = this.next();
        this.back();
        switch (c) {
            case '"':
                return this.handleCString();
            case '{':
                return this.handleObject();
            case '[':
                return this.handleArray();
            default:
                // A weird array element with a name, ignore the name and return the value
                this.handleString();
                if (this.next() === '=') {
                    return this.handleValue();
                }
        }
        return null;
    }

    protected handleAsyncData() {
        const result: any = {};

        let c = this.next();
        let name = 'missing';
        while (c === ',') {
            if (this.peek() !== '{') {
                name = this.handleString();
                if (this.next() === '=') {
                    result[name] = this.handleValue();
                }
            } else {
                // In some cases, such as -break-insert with multiple results
                // GDB does not return an array, so we have to identify that
                // case and convert result to an array
                // An example is (many fields removed to make example readable):
                // 3-break-insert --function staticfunc1
                // 3^done,bkpt={number="1",addr="<MULTIPLE>"},{number="1.1",func="staticfunc1",file="functions.c"},{number="1.2",func="staticfunc1",file="functions_other.c"}
                if (!Array.isArray(result[name])) {
                    result[name] = [result[name]];
                }
                result[name].push(this.handleValue());
            }
            c = this.next();
        }

        return result;
    }

    protected handleConsoleStream() {
        const msg = this.handleCString();
        if (msg) {
            this.gdb.emit('consoleStreamOutput', msg, 'stdout');
        }
    }

    protected handleLogStream() {
        const msg = this.handleCString();
        if (msg) {
            this.gdb.emit('consoleStreamOutput', msg, 'log');
        }
    }

    protected handleLine() {
        let c = this.next();
        if (!c) {
            return;
        }

        let token = '';

        if (c >= '0' && c <= '9') {
            token = this.handleToken(c);
            c = this.next();
        }

        switch (c) {
            case '^': {
                const rest = this.restOfLine();
                for (let i = 0; i < rest.length; i += 1000) {
                    const msg = i === 0 ? 'result' : '-cont-';
                    this.logger.verbose(
                        `GDB ${msg}: ${token} ${rest.substr(i, 1000)}`
                    );
                }
                const command = this.commandQueue[token];
                const resultClass = this.handleString();
                const resultData = this.handleAsyncData();
                resultData['cdt-token'] = token;
                if (command) {
                    resultData['cdt-command'] = command.command;
                    command.callback(resultClass, resultData);
                    delete this.commandQueue[token];
                } else {
                    // If result is an out-of-band error, we expect this is handled higher up.
                    // In fact currently only expected for '-exec-*' commands. Hence, only print
                    // as error, if result class other than 'error' where this is genuinely unexpected.
                    const message = `GDB response with no command: ${token}`;
                    if (resultClass === 'error') {
                        this.logger.verbose(message);
                    } else {
                        this.logger.error(message);
                    }
                }
                this.gdb.emit('resultAsync', resultClass, resultData);
                break;
            }
            case '~':
            case '@':
                this.handleConsoleStream();
                break;
            case '&':
                this.handleLogStream();
                break;
            case '=': {
                this.logger.verbose('GDB notify async: ' + this.restOfLine());
                const notifyClass = this.handleString();
                this.gdb.emit(
                    'notifyAsync',
                    notifyClass,
                    this.handleAsyncData()
                );
                break;
            }
            case '*': {
                this.logger.verbose('GDB exec async: ' + this.restOfLine());
                const execClass = this.handleString();
                this.gdb.emit('execAsync', execClass, this.handleAsyncData());
                break;
            }
            case '+': {
                this.logger.verbose('GDB status async: ' + this.restOfLine());
                const statusClass = this.handleString();
                this.gdb.emit(
                    'statusAsync',
                    statusClass,
                    this.handleAsyncData()
                );
                break;
            }
            case '(':
                // this is the (gdb) prompt and used
                // to know that GDB has started and is ready
                // for commands
                if (this.waitReady) {
                    this.waitReady();
                    this.waitReady = undefined;
                }
                break;
            default:
                // treat as console output. happens on Windows.
                this.back();
                this.gdb.emit(
                    'consoleStreamOutput',
                    this.restOfLine() + '\n',
                    'stdout'
                );
        }
    }
}
